def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []

    # Find monochromatic connected components that form rectangular frames.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == color and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            r0 = min(rr for rr, _ in comp)
            r1 = max(rr for rr, _ in comp)
            c0 = min(cc for _, cc in comp)
            c1 = max(cc for _, cc in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = {
                (rr, cc)
                for rr in range(r0, r1 + 1)
                for cc in range(c0, c1 + 1)
                if rr in (r0, r1) or cc in (c0, c1)
            }
            if set(comp) == border:
                boxes.append((r0, r1, c0, c1, color, border))

    frame_cells = set()
    for *_, border in boxes:
        frame_cells.update(border)

    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != 0 and (r, c) not in frame_cells:
                counts[color] = counts.get(color, 0) + 1

    out = [[0] * w for _ in range(h)]
    for r, c in frame_cells:
        out[r][c] = grid[r][c]

    for r0, r1, c0, c1, _, _ in boxes:
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        needed = (ih * iw + 1) // 2
        fill = next((color for color, count in counts.items()
                     if color not in (0,) and count == needed), None)
        if fill is None:
            continue
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if ((r - r0) + (c - c0)) % 2 == 0:
                    out[r][c] = fill

    return out
